import{_ as t,o as i,c as a,a0 as n}from"./chunks/framework.DPd3ST4h.js";const u=JSON.parse('{"title":"Review performance benchmark","description":"","frontmatter":{},"headers":[],"relativePath":"performance-benchmark.md","filePath":"performance-benchmark.md","lastUpdated":1793121966000}'),s={name:"performance-benchmark.md"};function r(o,e,l,d,c,p){return i(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="review-performance-benchmark" tabindex="-1">Review performance benchmark <a class="header-anchor" href="#review-performance-benchmark" aria-label="Permalink to &quot;Review performance benchmark&quot;">​</a></h1><p>Redline has a fixed 20-file performance corpus under <code>benchmark/performance/v1/</code>. It measures the bounded per-file review scheduler and records the effect of each integrated performance-epic change. The separate <a href="/projects/redline/model-execution-benchmark">model execution benchmark</a> selects Pi thinking, output, retry, deadline, and process-isolation policy.</p><p>The corpus contains:</p><ul><li>six ordinary TypeScript files;</li><li>four TypeScript test files;</li><li>three configuration files;</li><li>three documentation files;</li><li>two large TypeScript files;</li><li>two generated-like JSON artifacts.</li></ul><p>Every change is intentionally clean. A run fails its quality gate if any file is omitted, produces invalid output, produces a finding, loses required coverage, or fails publication through the forge-neutral publication service.</p><h2 id="run-the-recorded-baseline" tabindex="-1">Run the recorded baseline <a class="header-anchor" href="#run-the-recorded-baseline" aria-label="Permalink to &quot;Run the recorded baseline&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> benchmark:performance</span></span></code></pre></div><p>The command executes Redline&#39;s TypeScript source directly, runs the fixed corpus through the production bundle loader, prompt builder, harness contract, result validator, output writer, PR-level contract, and publication service, then writes:</p><ul><li><code>benchmark/performance/v1/baseline/report.json</code></li><li><code>benchmark/performance/v1/baseline/report.md</code></li></ul><p>Recorded mode performs no network requests. It uses checked-in per-file model durations and bounded timing samples from named production Action runs. The report marks the SLO gate as <strong>not eligible</strong> because recorded data cannot prove current live latency.</p><h2 id="typescript-source-runtime-measurement" tabindex="-1">TypeScript source runtime measurement <a class="header-anchor" href="#typescript-source-runtime-measurement" aria-label="Permalink to &quot;TypeScript source runtime measurement&quot;">​</a></h2><p><code>mise run benchmark:source-runtime</code> measures the pinned runtimes against direct TypeScript source. It runs five context-only CLI validation starts and three deterministic echo review pipelines per runtime. The checked-in captures are under <code>benchmark/source-runtime/v1/</code>.</p><table tabindex="0"><thead><tr><th>Runtime</th><th style="text-align:right;">CLI startup p50/p95</th><th style="text-align:right;">Echo review p50/p95</th></tr></thead><tbody><tr><td>Node 24.21.0</td><td style="text-align:right;">64/67 ms</td><td style="text-align:right;">165/184 ms</td></tr><tr><td>Bun 1.4.4</td><td style="text-align:right;">13/14 ms</td><td style="text-align:right;">79/85 ms</td></tr></tbody></table><p>These local process samples exclude dependency installation, harness installation, indexing, model calls, network latency, and publication. On pull requests, the CI source-runtime matrix separately times the root composite action end to end under both selected runtimes and uploads <code>action.json</code> with the runtime, outcome, and duration.</p><p>PR #168 workflow run <code>40121913292</code> supplied the first GitHub-hosted runner capture:</p><table tabindex="0"><thead><tr><th>Runtime</th><th style="text-align:right;">CLI startup p50/p95</th><th style="text-align:right;">Echo review p50/p95</th><th style="text-align:right;">Composite action</th></tr></thead><tbody><tr><td>Node 24.21.0</td><td style="text-align:right;">145/156 ms</td><td style="text-align:right;">371/372 ms</td><td style="text-align:right;">14,097 ms</td></tr><tr><td>Bun 1.4.4</td><td style="text-align:right;">16/16 ms</td><td style="text-align:right;">123/125 ms</td><td style="text-align:right;">9,771 ms</td></tr></tbody></table><p>Both composite-action runs succeeded with the deterministic echo harness and indexing disabled. This is one runner capture, not a latency distribution. Bun is faster in the bounded local and CI captures, but model work dominates live reviews, so Node remains the default and these results do not claim an end-to-end model-bound latency improvement. The complete capture is checked in at <code>benchmark/source-runtime/v1/ci-pr-168.json</code>.</p><h2 id="ci-dependency-store-cache" tabindex="-1">CI dependency-store cache <a class="header-anchor" href="#ci-dependency-store-cache" aria-label="Permalink to &quot;CI dependency-store cache&quot;">​</a></h2><p>The production review action executes trusted TypeScript source without running Corepack, installing project dependencies, or type-checking. CI and documentation jobs retain the frozen dependency install through <code>.github/actions/install-dependencies</code>:</p><ul><li>pnpm is pinned to 10.33.0 and lifecycle scripts are disabled;</li><li>the content-addressed store uses an exact versioned key bound to runner OS, architecture, Node 24, pnpm 10.33.0, and the complete <code>pnpm-lock.yaml</code> digest;</li><li>the cache contains only the dedicated pnpm store, never <code>node_modules</code>;</li><li>a restore failure becomes a normal frozen install, and a restored store that fails installation is removed and retried once from an empty store;</li><li>cache saves are skipped above 512 MiB and save failures do not change the install result;</li><li>every job writes and uploads versioned JSON telemetry with cache disposition, install duration, and store size.</li></ul><p>PR #169 workflow run <code>40125277504</code> measured a 113.55 MiB store. Four exact-key misses installed in 1,043–1,489 ms (p50 1,160 ms); six warm exact-key hits installed in 504–1,089 ms (p50 546 ms). Removing project setup from the timed review action reduced the observed Node smoke from 14,097 ms to 6,712–8,651 ms and the Bun smoke from 9,771 ms to 4,284–7,151 ms. These are deterministic echo-harness samples, not model-bound latency measurements.</p><p><code>node_modules</code> remains uncached because this capture does not prove a net benefit over restoring the 113.55 MiB pnpm store and running the frozen linker. The complete evidence is checked in at <code>benchmark/dependency-install/v1/ci-pr-169.json</code>.</p><p>The baseline uses four workers and largest-diff-first scheduling. It retains 1,208 seconds of total modeled model work and models 340 seconds of review wall time. The previous sequential baseline reported 1,260.8 seconds warm-index p95 and 1,474.3 seconds cold-index p95. The four-worker baseline reports 392.8 seconds warm and 606.3 seconds cold. Both are below the epic targets, but the report remains SLO-ineligible until at least five current live fixed-corpus runs pass the quality gate.</p><h2 id="review-eligibility-evidence" tabindex="-1">Review eligibility evidence <a class="header-anchor" href="#review-eligibility-evidence" aria-label="Permalink to &quot;Review eligibility evidence&quot;">​</a></h2><p>The separate deterministic report under <code>benchmark/review-eligibility/v1/</code> measures low-value generated classes before Redline enables repository-specific exclusions. PR #171 run <code>40132029782</code> observed one raw <code>benchmark/**/capture.json</code> file with 63,669 diff bytes, about 15,918 estimated input tokens, 3,987 ms of model work, and no findings or rejected candidates. That file represented 30.03% of the pull request&#39;s diff bytes.</p><p>Redline therefore excludes only raw benchmark captures in its exact-base <code>.redline/review-eligibility.json</code>. Generated benchmark reports remain reviewable because they carry conclusions. No generated snapshots were observed, so snapshot exclusions remain configurable rather than default. Run <code>mise run benchmark:review-eligibility</code> to regenerate the JSON and Markdown report. See <a href="/projects/redline/review-eligibility">review eligibility</a> for the policy and trust boundary.</p><h2 id="prompt-volume-comparison" tabindex="-1">Prompt-volume comparison <a class="header-anchor" href="#prompt-volume-comparison" aria-label="Permalink to &quot;Prompt-volume comparison&quot;">​</a></h2><p>The performance benchmark assembles a full-file baseline prompt in a recorded prepass, then executes the focused production prompt. The prepass does not contribute to review latency. Both variants use the same policy, diff, indexed context, and recorded clean responses.</p><p>On the representative 20-file corpus, focused source selection reduces aggregate prompt volume from 388,473 to 266,257 bytes: 122,216 bytes, or 31.46%. The median file saves 2,434 bytes, or 15.34%. The stable four-characters-per-token estimate falls from 97,132 to 66,579 input tokens, a reduction of 30,553. Every corpus file is smaller with the focused strategy. The review-quality corpus separately replays both strategies and records unchanged root-cause, evidence, false-positive, and coverage results.</p><h2 id="checkout-and-exact-revision-measurement" tabindex="-1">Checkout and exact-revision measurement <a class="header-anchor" href="#checkout-and-exact-revision-measurement" aria-label="Permalink to &quot;Checkout and exact-revision measurement&quot;">​</a></h2><p>The separate <a href="/projects/redline/checkout-benchmark">checkout benchmark</a> compares full-history, shallow exact-revision, and blobless partial Git strategies on pinned Redline and Visual Studio Code revisions. It separates checkout, exact fetch, object hydration, context-bundle, index-source-export, object-store, and critical-path measurements. Synthetic tests prove fork, force-push, merge-commit, and shallow-history behavior before any production change.</p><p>Final workflow run <a href="https://github.com/dragoscirjan/redline/actions/runs/40194071271" target="_blank" rel="noreferrer"><code>40194071271</code></a> completed five samples per repository and strategy. Full checkout was stable and fastest on Redline at 1.598 seconds p95. On VS Code, full checkout was 146.676 seconds p95; shallow was 37.245 seconds and partial was 61.240 seconds, but both alternatives changed the authoritative context bundle and failed correctness. Redline therefore retains full checkout. No correct uncached alternative crossed the combined 30-second and 5% gate, so Git object caching remains out of scope.</p><h2 id="run-an-opt-in-live-capture" tabindex="-1">Run an opt-in live capture <a class="header-anchor" href="#run-an-opt-in-live-capture" aria-label="Permalink to &quot;Run an opt-in live capture&quot;">​</a></h2><p>A live capture uses the pinned profile:</p><ul><li>Pi;</li><li>OpenRouter&#39;s OpenAI-compatible endpoint;</li><li><code>z-ai/glm-5.3-flash</code>;</li><li>CGC 0.5.7 context;</li><li>bounded parallel execution with four workers.</li></ul><p>Run at least five fixed-corpus repetitions to make the SLO gate eligible. This minimum applies to benchmark executions, not to the number of historical workflow-stage samples in each cache condition:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REDLINE_LIVE_BENCHMARK</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REDLINE_HARNESS=pi </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REDLINE_MODEL_CONFIG=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;{&quot;provider&quot;:&quot;openrouter&quot;,&quot;endpoint&quot;:&quot;https://openrouter.ai/api/v1&quot;,&quot;model&quot;:&quot;z-ai/glm-5.3-flash&quot;}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REDLINE_MODEL_AUTH=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;{&quot;openrouter&quot;:&quot;...&quot;}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mise </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> benchmark:performance-live</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --runs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/redline-performance-live</span></span></code></pre></div><p>The live output path is mandatory. Live reports use owner-only file permissions. The selected credential and endpoint credential value are never written to the report.</p><p>The warm-index target is p95 at or below 10 minutes. The cold-index target is p95 at or below 15 minutes. The warm condition represents a validated exact-base cache hit and therefore requires <code>indexMs: 0</code>; the cold condition includes provider indexing. A target cannot pass unless all live runs pass the quality gate.</p><h2 id="measurements" tabindex="-1">Measurements <a class="header-anchor" href="#measurements" aria-label="Permalink to &quot;Measurements&quot;">​</a></h2><p>Each report contains:</p><ul><li>review wall time, total model work, configured concurrency, and maximum active model calls;</li><li>publication duration;</li><li>per-file queue wait and model duration;</li><li>process startup and time to first streamed model text when available;</li><li>per-file and aggregate full-file baseline bytes, focused prompt bytes, byte reduction, and median reduction;</li><li>baseline and focused estimated input tokens plus estimated token reduction;</li><li>bounded stdout/stderr byte counts and estimated output tokens;</li><li>output truncation state;</li><li>warm and cold index timing distributions;</li><li>omissions, invalid records, rejected candidates, findings, coverage, and publication status.</li></ul><p>The four-characters-per-token values are estimates. Actual token counts and cost remain <code>null</code> until a harness exposes bounded provider usage metadata.</p><p>Reports never contain prompts, source text, model responses, raw reasoning, credentials, or publication tokens.</p><h2 id="timing-boundaries" tabindex="-1">Timing boundaries <a class="header-anchor" href="#timing-boundaries" aria-label="Permalink to &quot;Timing boundaries&quot;">​</a></h2><p>The checked-in index profile uses bounded timings from named production runs. Live corpus runs combine their measured review wall time with those fixed production samples, including sampled production publication latency. The locally measured publication duration is reported for each run but is not added to the end-to-end totals. The report states this limitation explicitly. Issue #153 owns the broader CGC/GitNexus value and latency comparison.</p><p>Publication uses the production forge-neutral service with an in-memory publisher. It measures validation, rendering, planning, and orchestration, but not GitHub network latency.</p>`,47)])])}const m=t(s,[["render",r]]);export{u as __pageData,m as default};
